async bulkCleanup(): Promise<{
    scannedCount: number;
    removedCount: number;
    removedFiles: string[];
    errors: Array<{ file: string; error: string }>;
  }> {
    this.ensureInitialized();

    const files = this.db.prepare('SELECT DISTINCT file_path FROM functions').all() as Array<{ file_path: string }>;
    const removedFiles: string[] = [];
    const errors: Array<{ file: string; error: string }> = [];
    let removedCount = 0;
    let scannedCount = 0;

    for (const { file_path: fp } of files) {
      scannedCount++;
      try {
        await fs.access(fp);
      } catch {
        const result = this.db.prepare('DELETE FROM functions WHERE file_path = ?').run(fp);
        removedCount += result.changes;
        removedFiles.push(fp);
      }
    }

    return { scannedCount, removedCount, removedFiles, errors };
  }:loop-query

async deepSync(
    projectRoot?: string,
    progressCallback?: (progress: { current: number; total: number; file: string }) => void
  ): Promise<{
    syncedFiles: number;
    addedFunctions: number;
    updatedFunctions: number;
    removedFunctions: number;
    errors: Array<{ file: string; error: string }>;
  }> {
    this.ensureInitialized();

    let syncedFiles = 0;
    let totalAdded = 0;
    let totalUpdated = 0;
    let totalRemoved = 0;
    const errors: Array<{ file: string; error: string }> = [];

    // Discover files from the filesystem when projectRoot is provided
    let files: string[];
    if (projectRoot) {
      const discovered = await discoverFiles(projectRoot, {
        extensions: ALL_EXTENSIONS,
      });
      files = discovered.sort();
    } else {
      // Fallback: sync files already in the index
      const rows = this.db.prepare('SELECT DISTINCT file_path FROM functions').all() as Array<{ file_path: string }>;
      files = rows.map(r => r.file_path);
    }

    const total = files.length;

    for (let i = 0; i < files.length; i++) {
      const fp = files[i];
      if (progressCallback) {
        progressCallback({ current: i + 1, total, file: fp });
      }
      try {
        const result = await this.synchronizeFile(fp);
        if (result) {
          syncedFiles++;
          totalAdded += result.added;
          totalUpdated += result.updated;
          totalRemoved += result.removed;
        }
      } catch (error) {
        errors.push({
          file: fp,
          error: error instanceof Error ? error.message : String(error)
        });
      }
    }

    // Clean up stale entries for files that no longer exist on disk
    const allIndexed = this.db.prepare('SELECT DISTINCT file_path FROM functions').all() as Array<{ file_path: string }>;
    for (const { file_path: fp } of allIndexed) {
      try {
        await fs.access(fp);
      } catch {
        // File deleted — remove its functions
        const result = this.db.prepare('DELETE FROM functions WHERE file_path = ?').run(fp);
        if (result.changes > 0) {
          totalRemoved += result.changes;
        }
      }
    }

    // Spec 13 — Extract git churn data after index is built and stale entries
    // are cleaned up. Runs before conventions mining so hotspot data is
    // available for reordering. Degrades gracefully when no repo exists.
    if (projectRoot) {
      try {
        extractChurn(this.db, projectRoot, { churnWindowMonths: 12 });
        // Compute hotspot scores from churn data
        computeHotspots(this.db);
      } catch (err) {
        // Churn extraction failure is non-fatal — continue without hotspot data.
        // Log the error so the agent/user knows hotspots are unavailable.
        const message = err instanceof Error ? err.message : String(err);
        console.warn(`[code-audit] Churn/hotspot extraction failed (non-fatal): ${message}`);
      }
    }

    // Spec 12 — Mine codebase conventions after sync when the functions table
    // has changed. Content-hash-based skip: stored hash avoids re-mining.
    const miningConfig: ConventionMiningConfig = {
      minCorpus: 20,
      pairConfidence: 0.9,
      modeShare: 0.8,
      maxConventionsPerDomain: 200,
    };
    const newHash = computeMinerInputHash(this.db, miningConfig);
    const oldHashRow = this.db.prepare(
      "SELECT value FROM meta WHERE key = 'conventions_hash'"
    ).get() as { value: string } | undefined;

    if (!oldHashRow || oldHashRow.value !== newHash) {
      const conventions = mineConventions(this.db, miningConfig, projectRoot);
      // Upsert: clear existing conventions, insert new ones
      const deleteStmt = this.db.prepare('DELETE FROM conventions');
      const insertStmt = this.db.prepare(
        `INSERT INTO conventions
         (domain, rule_id, antecedent, consequent, pattern, directory,
          file_path, line, support, total_cases, confidence,
          exemplar_file, exemplar_line, export_kind, hash)
         VALUES (@domain, @rule_id, @antecedent, @consequent, @pattern,
                 @directory, @file_path, @line, @support, @total_cases,
                 @confidence, @exemplar_file, @exemplar_line, @export_kind, @hash)`
      );

      const upsertAll = this.db.transaction(() => {
        deleteStmt.run();
        for (const c of conventions) {
          insertStmt.run({
            domain: c.domain,
            rule_id: c.rule_id,
            antecedent: c.antecedent ?? null,
            consequent: c.consequent ?? null,
            pattern: c.pattern ?? null,
            directory: c.directory ?? null,
            file_path: c.file_path ?? null,
            line: c.line ?? null,
            support: c.support,
            total_cases: c.total_cases,
            confidence: c.confidence,
            exemplar_file: c.exemplar_file ?? null,
            exemplar_line: c.exemplar_line ?? null,
            export_kind: (c as any).export_kind ?? null,
            hash: c.hash ?? null,
          });
        }
      });
      upsertAll();

      this.db.prepare(
        "INSERT OR REPLACE INTO meta (key, value) VALUES ('conventions_hash', ?)"
      ).run(newHash);
    }

    // Spec 14 — Populate graph caches after index is built
    try {
      populateCallGraphCache(this.db);
      populateImportGraphCache(this.db);
    } catch {
      // Graph cache population failure is non-fatal — continue without graph data
    }

    return {
      syncedFiles,
      addedFunctions: totalAdded,
      updatedFunctions: totalUpdated,
      removedFunctions: totalRemoved,
      errors
    };
  }:loop-query

async detectChangedFunctions(filePaths: string[]): Promise<{
    changedFunctions: EnhancedFunctionMetadata[];
    deletedFunctions: EnhancedFunctionMetadata[];
    changedFilePaths: string[];
    errors: Array<{ file: string; error: string }>;
  }> {
    this.ensureInitialized();

    const changedFunctions: EnhancedFunctionMetadata[] = [];
    const deletedFunctions: EnhancedFunctionMetadata[] = [];
    const changedFilePaths: string[] = [];
    const errors: Array<{ file: string; error: string }> = [];

    const { FunctionScanner } = await import('./functionScanner.js');

    for (const filePath of filePaths) {
      try {
        await fs.access(filePath);
      } catch {
        // File doesn't exist — remove all its functions
        const removed = this.db.prepare(
          'SELECT * FROM functions WHERE file_path = ?'
        ).all(filePath) as any[];
        if (removed.length > 0) {
          const parsed = removed.map((r: any) => this.rowToFunction(r));
          deletedFunctions.push(...parsed);
          this.db.prepare('DELETE FROM functions WHERE file_path = ?').run(filePath);
          changedFilePaths.push(filePath);
        }
        continue;
      }

      try {
        const scanner = new FunctionScanner();
        const fileContent = await fs.readFile(filePath, 'utf-8');
        const language = (filePath.endsWith('.ts') || filePath.endsWith('.tsx'))
          ? 'typescript' : 'javascript';
        const currentFunctions = await scanner.scanFunctions(fileContent, filePath, language);

        // Get existing functions for this file from DB
        const existing = this.db.prepare(
          'SELECT * FROM functions WHERE file_path = ?'
        ).all(filePath) as any[];

        // Build a name → existing-row map
        const existingByName = new Map<string, any>();
        for (const e of existing) {
          existingByName.set(e.name, e);
        }

        const currentNames = new Set(currentFunctions.map((f: any) => f.name));
        let fileChanged = false;

        for (const func of currentFunctions) {
          const existingRow = existingByName.get(func.name);
          // Convert scanner output to EnhancedFunctionMetadata shape
          const funcMeta: EnhancedFunctionMetadata = {
            ...func,
            complexity: (func as any).complexity,
            content_hash: computeContentHash(
              (func as any).body ?? (func as any).metadata?.body,
              (func as any).signature
            ),
          } as EnhancedFunctionMetadata;
          const newHash = funcMeta.content_hash!;

          if (!existingRow) {
            // New function
            changedFunctions.push(funcMeta);
            fileChanged = true;
          } else if (existingRow.content_hash !== newHash) {
            // Changed function
            changedFunctions.push(funcMeta);
            fileChanged = true;
          }
        }

        // Detect deleted functions
        for (const e of existing) {
          if (!currentNames.has(e.name)) {
            deletedFunctions.push(this.rowToFunction(e));
            fileChanged = true;
          }
        }

        if (fileChanged) {
          changedFilePaths.push(filePath);
        }

        // Sync the file into the index (upsert + deletes)
        await this.syncFileIndex(filePath, currentFunctions as FunctionMetadata[]);
      } catch (error) {
        errors.push({
          file: filePath,
          error: error instanceof Error ? error.message : String(error)
        });
      }
    }

    return { changedFunctions, deletedFunctions, changedFilePaths, errors };
  }:loop-query

