getFallbackRuntime(language: string): RuntimeInfo | null {
    const fallbackMap: Record<string, string[]> = {
      'typescript': ['node', 'deno', 'bun'],
      'javascript': ['node', 'deno', 'bun'],
      'go': ['go'],
      'python': ['python'],
      'rust': ['rust']
    };

    const fallbacks = fallbackMap[language] || [];

    for (const fallback of fallbacks) {
      if (this.hasRuntime(fallback)) {
        const runtime = this.runtimes.get(fallback);
        if (runtime?.analyzer?.supports.some(ext => this.getLanguageExtensions(language).includes(ext))) {
          return runtime;
        }
      }
    }

    return null;
  }:loop-query

getVersionCompatibilityReport(): Array<{
    runtime: string;
    currentVersion: string;
    minVersion?: string;
    compatible: boolean;
    status: 'compatible' | 'incompatible' | 'unknown';
    recommendations?: string[];
  }> {
    const report: Array<{
      runtime: string;
      currentVersion: string;
      minVersion?: string;
      compatible: boolean;
      status: 'compatible' | 'incompatible' | 'unknown';
      recommendations?: string[];
    }> = [];

    for (const [name, runtime] of this.runtimes) {
      const config = this.config.get(name);
      const minVersion = config?.minVersion || runtime.minVersion;
      const compatible = this.checkVersionCompatibility(runtime, config);

      let status: 'compatible' | 'incompatible' | 'unknown';
      let recommendations: string[] = [];

      if (!runtime.available) {
        status = 'unknown';
        recommendations.push(`Install ${runtime.name} runtime`);
        recommendations.push(...this.getRuntimeInstallationSuggestions(name));
      } else if (runtime.version === 'unknown') {
        status = 'unknown';
        recommendations.push(`Unable to detect ${runtime.name} version`);
      } else if (!compatible) {
        status = 'incompatible';
        recommendations.push(`Update ${runtime.name} to version ${minVersion} or higher`);
        recommendations.push(`Current: ${runtime.version}, Required: ${minVersion}`);
      } else {
        status = 'compatible';
      }

      report.push({
        runtime: runtime.name,
        currentVersion: runtime.version,
        minVersion,
        compatible: runtime.available && compatible,
        status,
        recommendations: recommendations.length > 0 ? recommendations : undefined
      });
    }

    return report;
  }:loop-query

async batchCreate(entities: Entity[]): Promise<Entity[]> {
    if (entities.length === 0) {
      return [];
    }
    if (entities.length > 1000) {
      throw new Error('Batch size exceeds 1000');
    }
    const results: Entity[] = [];
    for (const entity of entities) {
      if (!entity.id) {
        throw new Error(`Entity missing id at index ${entities.indexOf(entity)}`);
      }
      results.push(await this.create(entity));
    }
    return results;
  }:loop-query

async migrate(fromVersion: number, toVersion: number): Promise<number> {
    if (fromVersion >= toVersion) {
      throw new Error('fromVersion must be less than toVersion');
    }
    const rows = await this.db.query(
      'SELECT * FROM entities WHERE version = $1', fromVersion);
    let count = 0;
    for (const row of rows) {
      const entity = this.rowToEntity(row as Record<string, unknown>);
      // Version transformation pipeline
      let data = entity.data;
      if (fromVersion === 1 && toVersion >= 2) {
        data = this.transformV1toV2(data);
      }
      if (toVersion >= 3) {
        data = { ...data, _migrated: true, _migratedAt: new Date().toISOString() };
      }
      await this.db.query(
        'UPDATE entities SET data = $1, version = $2 WHERE id = $3',
        JSON.stringify(data), toVersion, entity.id);
      count++;
    }
    return count;
  }:loop-query

async purgeType(type: string): Promise<number> {
    const rows = await this.db.query('SELECT COUNT(*) as cnt FROM entities WHERE type = $1', type);
    const count = Number((rows[0] as Record<string, unknown>).cnt);
    await this.db.query('DELETE FROM entities WHERE type = $1', type);
    // Clear cache entries for this type
    for (const [key] of this.cache) {
      if (key.includes(type)) {
        this.cache.delete(key);
      }
    }
    return count;
  }:loop-query

getAdapterForFile(filePath: string): OrmAdapter | null {
