function exportLedger(
  db: Database.Database,
  since?: string,
): { runs: LedgerRunRecord[]; findings: LedgerFindingRecord[] } {
  const runParams: any[] = [];
  let runWhere = '';
  if (since) {
    runWhere = 'WHERE timestamp >= ?';
    runParams.push(since);
  }

  const runs = db.prepare(`
    SELECT
      run_id AS runId,
      timestamp,
      git_sha AS gitSha,
      git_dirty AS gitDirty,
      tool_version AS toolVersion,
      command,
      surface,
      scope,
      target,
      duration_ms AS durationMs,
      exit_status AS exitStatus
    FROM findings_ledger_runs
    ${runWhere}
    ORDER BY timestamp DESC
  `).all(...runParams) as any[];

  const runIds = runs.map((r) => r.runId);
  let findings: any[] = [];
  if (runIds.length > 0) {
    const placeholders = runIds.map(() => '?').join(',');
    findings = db.prepare(`
      SELECT
        run_id AS runId,
        analyzer,
        rule,
        severity,
        message,
        file,
        line,
        symbol,
        fingerprint
      FROM findings_ledger_findings
      WHERE run_id IN (${placeholders})
      ORDER BY run_id, id
    `).all(...runIds) as any[];
  }

  return {
    runs: runs.map((r) => ({
      ...r,
      gitDirty: !!r.gitDirty,
      timestamp: String(r.timestamp),
    })),
    findings: findings.map((f) => ({
      ...f,
      line: f.line ?? null,
      symbol: String(f.symbol ?? ''),
      fingerprint: String(f.fingerprint ?? ''),
    })),
  };
}:unknown

